def ql_loan_approval_myql_oracle(page):
    state = page.evaluate('() => $state')
    
    assert not True or page.locator('#fullName_div_25').is_visible(), 'true evaluated to true, however fullName_div_25 was not displayed'
    assert not True or page.locator('#age_div_70').is_visible(), 'true evaluated to true, however age_div_70 was not displayed'
    assert not True or page.locator('#hasLicense_div_104').is_visible(), 'true evaluated to true, however hasLicense_div_104 was not displayed'
    assert not (True and (state['age'] < 18)) or page.locator('#inSchool_div_183').is_visible(), 'true && age < 18 evaluated to true, however inSchool_div_183 was not displayed'
    assert not ((True and (state['age'] < 18)) and state['inSchool']) or page.locator('#grade_div_258').is_visible(), 'true && age < 18 && inSchool evaluated to true, however grade_div_258 was not displayed'
    assert not ((True and (not (((state['age'] < 18))))) and ((state['age'] >= 18) and (state['age'] <= 65))) or page.locator('#employed_div_360').is_visible(), 'true && !(age < 18) && age >= 18 && age <= 65 evaluated to true, however employed_div_360 was not displayed'
    assert not (((True and (not (((state['age'] < 18))))) and ((state['age'] >= 18) and (state['age'] <= 65))) and state['employed']) or page.locator('#jobTitle_div_445').is_visible(), 'true && !(age < 18) && age >= 18 && age <= 65 && employed evaluated to true, however jobTitle_div_445 was not displayed'
    assert not (((True and (not (((state['age'] < 18))))) and ((state['age'] >= 18) and (state['age'] <= 65))) and state['employed']) or page.locator('#yearsInJob_div_496').is_visible(), 'true && !(age < 18) && age >= 18 && age <= 65 && employed evaluated to true, however yearsInJob_div_496 was not displayed'
    assert not (((True and (not (((state['age'] < 18))))) and ((state['age'] >= 18) and (state['age'] <= 65))) and state['employed']) or page.locator('#monthlySalary_div_578').is_visible(), 'true && !(age < 18) && age >= 18 && age <= 65 && employed evaluated to true, however monthlySalary_div_578 was not displayed'
    assert not (((True and (not (((state['age'] < 18))))) and ((state['age'] >= 18) and (state['age'] <= 65))) and state['employed']) or page.locator('#monthlyExpenses_div_640').is_visible(), 'true && !(age < 18) && age >= 18 && age <= 65 && employed evaluated to true, however monthlyExpenses_div_640 was not displayed'
    assert not (((True and (not (((state['age'] < 18))))) and ((state['age'] >= 18) and (state['age'] <= 65))) and state['employed']) or page.locator('#annualSavings_div_713').is_visible(), 'true && !(age < 18) && age >= 18 && age <= 65 && employed evaluated to true, however annualSavings_div_713 was not displayed'
    assert state['annualSavings'] == (((state['monthlySalary'] - state['monthlyExpenses'])) * 12) if (((True and (not (((state['age'] < 18))))) and ((state['age'] >= 18) and (state['age'] <= 65))) and state['employed']) else True, ' annualSavings was expected to be (monthlySalary - monthlyExpenses) * 12 which equals ' + str((((state['monthlySalary'] - state['monthlyExpenses'])) * 12)) + ', but  annualSavings was  ' + str(state['annualSavings'])
    assert not (((True and (not (((state['age'] < 18))))) and ((state['age'] >= 18) and (state['age'] <= 65))) and (not ((state['employed'])))) or page.locator('#lookingForJob_div_822').is_visible(), 'true && !(age < 18) && age >= 18 && age <= 65 && !(employed) evaluated to true, however lookingForJob_div_822 was not displayed'
    assert not ((True and (not (((state['age'] < 18))))) and (not ((((state['age'] >= 18) and (state['age'] <= 65)))))) or page.locator('#retired_div_910').is_visible(), 'true && !(age < 18) && !(age >= 18 && age <= 65) evaluated to true, however retired_div_910 was not displayed'
    assert not (((True and (not (((state['age'] < 18))))) and (not ((((state['age'] >= 18) and (state['age'] <= 65)))))) and state['retired']) or page.locator('#yearsRetired_div_975').is_visible(), 'true && !(age < 18) && !(age >= 18 && age <= 65) && retired evaluated to true, however yearsRetired_div_975 was not displayed'
    assert not (((True and (not (((state['age'] < 18))))) and (not ((((state['age'] >= 18) and (state['age'] <= 65)))))) and state['retired']) or page.locator('#annualPension_div_1039').is_visible(), 'true && !(age < 18) && !(age >= 18 && age <= 65) && retired evaluated to true, however annualPension_div_1039 was not displayed'
    assert not (((True and (not (((state['age'] < 18))))) and (not ((((state['age'] >= 18) and (state['age'] <= 65)))))) and state['retired']) or page.locator('#healthcareExpenses_div_1101').is_visible(), 'true && !(age < 18) && !(age >= 18 && age <= 65) && retired evaluated to true, however healthcareExpenses_div_1101 was not displayed'
    assert not (((True and (not (((state['age'] < 18))))) and (not ((((state['age'] >= 18) and (state['age'] <= 65)))))) and state['retired']) or page.locator('#netPension_div_1180').is_visible(), 'true && !(age < 18) && !(age >= 18 && age <= 65) && retired evaluated to true, however netPension_div_1180 was not displayed'
    assert state['netPension'] == (state['annualPension'] - state['healthcareExpenses']) if (((True and (not (((state['age'] < 18))))) and (not ((((state['age'] >= 18) and (state['age'] <= 65)))))) and state['retired']) else True, ' netPension was expected to be annualPension - healthcareExpenses which equals ' + str((state['annualPension'] - state['healthcareExpenses'])) + ', but  netPension was  ' + str(state['netPension'])
    assert not True or page.locator('#seniorDiscount_div_1296').is_visible(), 'true evaluated to true, however seniorDiscount_div_1296 was not displayed'
    assert state['seniorDiscount'] == ((state['age'] >= 65) and state['retired']) if True else True, ' seniorDiscount was expected to be age >= 65 && retired which equals ' + str(((state['age'] >= 65) and state['retired'])) + ', but  seniorDiscount was  ' + str(state['seniorDiscount'])
    assert not True or page.locator('#income_div_1398').is_visible(), 'true evaluated to true, however income_div_1398 was not displayed'
    assert not True or page.locator('#monthlyDebts_div_1446').is_visible(), 'true evaluated to true, however monthlyDebts_div_1446 was not displayed'
    assert not True or page.locator('#hasCoSigner_div_1501').is_visible(), 'true evaluated to true, however hasCoSigner_div_1501 was not displayed'
    assert not True or page.locator('#loanAmount_div_1564').is_visible(), 'true evaluated to true, however loanAmount_div_1564 was not displayed'
    assert not True or page.locator('#interestRate_div_1608').is_visible(), 'true evaluated to true, however interestRate_div_1608 was not displayed'
    assert not True or page.locator('#loanTerm_div_1666').is_visible(), 'true evaluated to true, however loanTerm_div_1666 was not displayed'
    assert not True or page.locator('#totalInterest_div_1709').is_visible(), 'true evaluated to true, however totalInterest_div_1709 was not displayed'
    assert state['totalInterest'] == (lambda div: ((((state['loanAmount'] * state['interestRate']) * state['loanTerm'])) // div) if div != 0 else 0)(100) if True else True, ' totalInterest was expected to be (loanAmount * interestRate * loanTerm) / 100 which equals ' + str((lambda div: ((((state['loanAmount'] * state['interestRate']) * state['loanTerm'])) // div) if div != 0 else 0)(100)) + ', but  totalInterest was  ' + str(state['totalInterest'])
    assert not True or page.locator('#totalRepayment_div_1809').is_visible(), 'true evaluated to true, however totalRepayment_div_1809 was not displayed'
    assert state['totalRepayment'] == (state['loanAmount'] + state['totalInterest']) if True else True, ' totalRepayment was expected to be loanAmount + totalInterest which equals ' + str((state['loanAmount'] + state['totalInterest'])) + ', but  totalRepayment was  ' + str(state['totalRepayment'])
    assert not True or page.locator('#monthlyPayment_div_1892').is_visible(), 'true evaluated to true, however monthlyPayment_div_1892 was not displayed'
    assert state['monthlyPayment'] == (lambda div: (state['totalRepayment'] // div) if div != 0 else 0)(((state['loanTerm'] * 12))) if True else True, ' monthlyPayment was expected to be totalRepayment / (loanTerm * 12) which equals ' + str((lambda div: (state['totalRepayment'] // div) if div != 0 else 0)(((state['loanTerm'] * 12)))) + ', but  monthlyPayment was  ' + str(state['monthlyPayment'])
    assert not True or page.locator('#loanApproved_div_1984').is_visible(), 'true evaluated to true, however loanApproved_div_1984 was not displayed'
    assert state['loanApproved'] == ((((state['income'] > 50000) and (state['monthlyDebts'] < 10000))) or state['hasCoSigner']) if True else True, ' loanApproved was expected to be (income > 50000 && monthlyDebts < 10000) || hasCoSigner which equals ' + str(((((state['income'] > 50000) and (state['monthlyDebts'] < 10000))) or state['hasCoSigner'])) + ', but  loanApproved was  ' + str(state['loanApproved'])
    assert not (True and state['loanApproved']) or page.locator('#approvalMessage_div_2114').is_visible(), 'true && loanApproved evaluated to true, however approvalMessage_div_2114 was not displayed'
    assert state['approvalMessage'] == 'Approved' if (True and state['loanApproved']) else True, ' approvalMessage was expected to be "Approved" which equals ' + str('Approved') + ', but  approvalMessage was  ' + str(state['approvalMessage'])
    assert not (True and (not ((state['loanApproved'])))) or page.locator('#not_approvalMessage_div_2214').is_visible(), 'true && !(loanApproved) evaluated to true, however not_approvalMessage_div_2214 was not displayed'
    assert state['not_approvalMessage'] == 'Not Approved' if (True and (not ((state['loanApproved'])))) else True, ' not_approvalMessage was expected to be "Not Approved" which equals ' + str('Not Approved') + ', but  not_approvalMessage was  ' + str(state['not_approvalMessage'])
